import { useQueries } from '@tanstack/react-query';
import { format } from 'date-fns';
import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { voucherApi } from '~/entities/voucher/api/voucher-api';
import { DEFAULT_VOUCHER_PAGING, DEFAULT_VOUCHER_PARAMS } from '~/entities/voucher/model/constants';
import { queries } from '~/shared/api/query-keys';

type UseVoucherListsReturn = {
  myVoucherList: VoucherItemDTO[];
  allVoucherList: VoucherItemDTO[];
  isLoading: boolean;
  refetchVoucherLists: () => Promise<void>;
  findVoucherById: (vouchId: string) => Promise<VoucherItemDTO | undefined>;
};

export const useVoucherLists = (): UseVoucherListsReturn => {
  const [myVoucherQuery, allVoucherQuery] = useQueries({
    queries: [
      {
        ...queries.voucher.myVoucherList({
          paging: DEFAULT_VOUCHER_PAGING,
          search: DEFAULT_VOUCHER_PARAMS,
        }),
        queryFn: () =>
          voucherApi.getMyVoucherList({
            paging: DEFAULT_VOUCHER_PAGING,
            search: DEFAULT_VOUCHER_PARAMS,
          }),
      },
      {
        ...queries.voucher.allVoucherList({}),
        queryFn: () => voucherApi.getAllVoucherList({}),
      },
    ],
  });

  const myVoucherList = myVoucherQuery.data?.result?.list ?? [];
  const allVoucherList = allVoucherQuery.data ?? [];

  const sortedAllVoucherList = [...allVoucherList].sort((a, b) => {
    const aVal = Number(format(a.rcvfverUseStartDt ?? '', 'yyyyMMdd'));
    const bVal = Number(format(b.rcvfverUseStartDt ?? '', 'yyyyMMdd'));
    if (bVal > aVal) return 1;
    if (bVal < aVal) return -1;
    if (a.vouchNm!.toUpperCase() > b.vouchNm!.toUpperCase()) return 1;
    if (a.vouchNm!.toUpperCase() < b.vouchNm!.toUpperCase()) return -1;
    return 0;
  });

  const refetchVoucherLists = async () => {
    await Promise.all([myVoucherQuery.refetch(), allVoucherQuery.refetch()]);
  };

  const findVoucherById = async (vouchId: string): Promise<VoucherItemDTO | undefined> => {
    let voucher = myVoucherList.find((v) => v.vouchId === vouchId);
    if (voucher) return voucher;

    voucher = sortedAllVoucherList.find((v) => v.vouchId === vouchId);
    if (voucher) return voucher;

    // If not found in cached lists, fetch fresh data
    await refetchVoucherLists();

    return myVoucherList.find((v) => v.vouchId === vouchId) ?? sortedAllVoucherList.find((v) => v.vouchId === vouchId);
  };

  return {
    myVoucherList,
    allVoucherList: sortedAllVoucherList,
    isLoading: myVoucherQuery.isLoading || allVoucherQuery.isLoading,
    refetchVoucherLists,
    findVoucherById,
  };
};
